const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');
return [{ json: { ...$json, timestamp, signature } }];

const res = $input.first().json;
const raw = (res && res.data) || {};
const starts = [];
for (const day of Object.keys(raw)) {
  for (const slot of raw[day] || []) {
    if (slot && slot.start) starts.push(slot.start);
  }
}
starts.sort();
const slots = starts.slice(0, 3).map((iso) => {
  const d = new Date(iso);
  const label = d.toLocaleString('en-US', { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: 'UTC' }) + ' UTC';
  return { iso, label };
});
return [{ json: { slots } }];

const text = $input.first().json.choices[0].message.content;
const withoutThoughts = text.replace(/<thought>[\s\S]*?<\/thought>/gi, '');
const cleaned = withoutThoughts.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
const parsed = JSON.parse(cleaned);
const bookingLink = $vars.CAL_COM_BOOKING_LINK || 'https://cal.com/your-team/intro';
const slots = ($('Parse Available Slots').first().json.slots) || [];
let cta = bookingLink;
if (slots.length > 0) {
  const list = slots.map((s) => `- ${s.label}`).join('\n');
  cta = `A few times that work:\n${list}\n\nOr pick any other time here: ${bookingLink}`;
}
parsed.body = parsed.body.replace('{{booking_link}}', cta);
return [{ json: { leadId: $('Sign: Get Prompt').first().json.leadId, orgId: $('Sign: Get Prompt').first().json.orgId, agentId: $('GET Agent Prompt (scheduler)').first().json.agent.id, bookingLink, availableSlots: slots, ...parsed } }];

const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const p = $('Parse Booking Message').first().json;
const messageId = $json.messageId;
const threadId = $json.threadId;
const body = { event: 'meeting.booked', orgId: p.orgId, leadId: p.leadId, agentType: 'scheduler', input: {}, output: { bookingLink: p.bookingLink, subject: p.subject, body: p.body, messageId, threadId }, requiresHumanReview: false };
const rawBody = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { rawBody, timestamp, signature } }];
